import{_ as o,l as i,o as e,c as p,v as r,p as l,x as t,d as c,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"应用层背压","description":"","frontmatter":{"title":"应用层背压","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/app-backpressure.md","filePath":"cs/app-backpressure.md","lastUpdated":1789023840000}'),h={name:"cs/app-backpressure.md"};function u(_,a,m,P,f,E){const s=i("Mermaid");return e(),p("div",null,[a[1]||(a[1]=r('<h1 id="应用层背压" tabindex="-1">应用层背压 <a class="header-anchor" href="#应用层背压" aria-label="Permalink to &quot;应用层背压&quot;">​</a></h1><div class="epigraph"><p>慢消费者必须让生产者少发：窗口、阻塞写、队列上限或显式信号。否则内存当无限缓冲，延迟与 OOM 替代了丢包。</p><footer>—— 据 TCP 窗口对照；Reactive Streams 背压；RFC 9113 流控整理</footer></div><p><a href="/cs/tcp-window">TCP 窗口</a> 与 <a href="/cs/pause-pfc">PFC</a> 已给下层反压。<a href="/cs/c10k-concurrency">C10K</a> 的事件循环若盲目 <code>read</code> 会堆内存。<a href="/cs/retry-idempotency">上一课</a> 的重试会加重生产者。缺口是<strong>应用背压</strong>：把反压接到业务。本课结束计算机网络进阶；下一课程是数据库进阶。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>运输窗口满则 <code>write</code> 阻塞或 EAGAIN，这是 TCP 背压。应用若在用户态无限队列「先收着」，等于把膨胀搬进进程，心跳仍绿、业务已死。H2/QUIC 每流窗口是应用可见的运输背压。Reactive 流 <code>request(n)</code> 显式拉。令牌桶在入口限速是策略背压。SSE 若生产快于浏览器，要停生成器。</p><p>不要把杀进程当背压。</p><p><span class="marginnote">HTTP/2 流控。Reactive Streams 规范。本课钉原则。</span></p><h3 id="有界缓冲才是反压" tabindex="-1">有界缓冲才是反压 <a class="header-anchor" href="#有界缓冲才是反压" aria-label="Permalink to &quot;有界缓冲才是反压&quot;">​</a></h3><p>无限用户态队列取消 rwnd 的意义。可与 PFC、H2 窗口叠三层。重试在满载时要停。「先打进队列」只是改名膨胀。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：无限队列 / 有界队列阻塞 / 窗口 / 丢弃策略。画：快生产 → 信号 → 减速。与 DCTCP 浅队列同构，一层应用。</p>',11)),(e(),l(d,null,{default:t(()=>[n(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROD%5B%22%E7%94%9F%E4%BA%A7%E8%80%85%22%5D%20--%3E%20Q%5B%22%E6%9C%89%E7%95%8C%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20CONS%5B%22%E6%B6%88%E8%B4%B9%E8%80%85%22%5D%0A%20%20FULL%5B%22%E6%BB%A1%22%5D%20--%3E%20BP%5B%22%E9%98%BB%E5%A1%9E%E6%88%96%E7%AA%97%E5%8F%A3%E5%87%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>gRPC 流控、TCP rwnd、PFC 可叠三层；只开一层会在其它层爆。重试在背压时要停。负载均衡把溢出转到它机是横向背压。测量：队列深度与 p99，不是只看 iperf。</p><p>与端到端：最终仍要消费者处理完，背压只是保护途中内存。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入某语言异步库的全部 API。数据库进阶从 SQL 聚合另起，不在此插入。后课默认：应用必须有界缓冲并向下反压。</p><p>「先打进 Kafka 再算」只是把膨胀换了个名字，仍要有界。</p><p>上一课留下的缺口在本课收口；「应用层背压」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/sql-aggregation">聚合与 GROUP BY</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无限用户态队列取消了运输窗口的意义。</li><li>用窗口、有界阻塞或显式 request。</li><li>与 PFC/rwnd 分层叠，不要只信一层。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9113 流控；TCP 窗口；Reactive Streams。</li></ul>',10))])}const A=o(h,[["render",u]]);export{T as __pageData,A as default};
